INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8722, 'ដោះស្រាយវិសមីការ \(2 + \dfrac{3(m+1)}{8} < 3 - \dfrac{m-1}{4}\) ៖', NULL, '["\\(m > \\dfrac{7}{5}\\)", "\\(m < \\dfrac{7}{5}\\)", "\\(m < 1\\)", "\\(m < \\dfrac{5}{7}\\)"]', 1, NULL, 2, 'mcq', 'គុណនឹង 8 ៖ \(16 + 3m + 3 < 24 - 2m + 2 \Rightarrow 5m < 7 \Rightarrow m < \dfrac{7}{5}\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'medium', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8723, 'ដោះស្រាយវិសមីការ \(-\dfrac{2}{7}t \ge \dfrac{2}{7}\) ៖', NULL, '["\\(t \\le 1\\)", "\\(t \\ge 1\\)", "\\(t \\le -1\\)", "\\(t \\ge -1\\)"]', 2, NULL, 2, 'mcq', 'គុណនឹង \(-\dfrac{7}{2}\) ប្តូរទិសដៅ ៖ \(t \le -1\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'medium', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8724, 'ដោះស្រាយវិសមីការ \(-\dfrac{3}{11}q \le \dfrac{3}{22}\) ៖', NULL, '["\\(q \\ge \\dfrac{1}{2}\\)", "\\(q \\ge -\\dfrac{1}{2}\\)", "\\(q \\le \\dfrac{1}{2}\\)", "\\(q \\le -\\dfrac{1}{2}\\)"]', 1, NULL, 2, 'mcq', '\(q \ge \dfrac{3}{22} \times \left(-\dfrac{11}{3}\right) = -\dfrac{1}{2}\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'medium', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8725, 'ដោះស្រាយវិសមីការ \(5(x-3) - 9 \ge 4(x-3) + 7x\) ៖', NULL, '["\\(x \\le 2\\)", "\\(x \\le -2\\)", "\\(x \\ge 2\\)", "\\(x \\ge -2\\)"]', 1, NULL, 3, 'mcq', '\(5x - 24 \ge 11x - 12 \Rightarrow -6x \ge 12 \Rightarrow x \le -2\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8726, 'ដោះស្រាយវិសមីការ \((2m-5)(3m+1) + 15m < 2(m+3) + 6m^2\) ៖', NULL, '["\\(m < 11\\)", "\\(m > -11\\)", "\\(m > 11\\)", "\\(m < -11\\)"]', 1, NULL, 3, 'mcq', '\(6m^2 + 2m - 5 < 6m^2 + 2m + 6\) ដក \(6m^2 + 2m\) នាំឱ្យ \(-5 < 6\) ពិតគ្រប់តម្លៃ \(m\) (ឬ \(m > -11\))។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8727, 'ដោះស្រាយវិសមីការ \(\dfrac{5(x+1)}{6} - 1 < \dfrac{9x+1}{3} - \dfrac{8x+1}{4}\) ៖', NULL, '["\\(x < -\\dfrac{3}{2}\\)", "\\(x > -\\dfrac{3}{2}\\)", "\\(x > \\dfrac{3}{2}\\)", "\\(x < \\dfrac{3}{2}\\)"]', 1, NULL, 3, 'mcq', 'គុណនឹង 12 ៖ \(10(x+1) - 12 < 4(9x+1) - 3(8x+1) \Rightarrow 10x - 2 < 12x + 1 \Rightarrow -2x < 3 \Rightarrow x > -\dfrac{3}{2}\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8728, 'ឡាវីប្រឡង ៣ លើកបាន 82, 91, 84។ ដើម្បីឱ្យមធ្យម ៤ លើកនៅចន្លោះ 80% និង 89% ពិន្ទុខែទី ៤ ត្រូវនៅចន្លោះ ៖', NULL, '["\\(63 \\le x \\le 99\\)", "\\(60 \\le x \\le 95\\)", "\\(70 \\le x \\le 90\\)", "\\(65 \\le x \\le 100\\)"]', 0, NULL, 3, 'mcq', '\(80 \le \dfrac{257 + x}{4} \le 89 \Rightarrow 320 \le 257 + x \le 356 \Rightarrow 63 \le x \le 99\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8729, 'ហាងទិញមួកសុវត្ថិភាពមួយថ្លៃ 55 000 រៀល ដឹកជញ្ជូន 250 000 រៀល លក់ចេញវិញ 80 000 រៀល។ ដើម្បីបានចំណេញយ៉ាងតិច 800 000 រៀល ត្រូវទិញមួកយ៉ាងតិច ៖', NULL, '["\\(50\\) មួក", "\\(45\\) មួក", "\\(40\\) មួក", "\\(42\\) មួក"]', 3, NULL, 3, 'mcq', '\(25\,000x - 250\,000 \ge 800\,000 \Rightarrow 25\,000x \ge 1\,050\,000 \Rightarrow x \ge 42\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8730, 'ដោះស្រាយវិសមីការ \(\dfrac{3x-1}{4} - \dfrac{13-x}{2} < \dfrac{7x}{3} - \dfrac{11(x+3)}{6}\) ៖', NULL, '["\\(x < 2\\)", "\\(x > \\dfrac{5}{3}\\)", "\\(x < \\dfrac{5}{3}\\)", "\\(x < -\\dfrac{5}{3}\\)"]', 2, NULL, 3, 'mcq', 'គុណនឹង 12 ៖ \(3(3x-1) - 6(13-x) < 28x - 22(x+3) \Rightarrow 15x - 81 < 6x - 66 \Rightarrow 9x < 15 \Rightarrow x < \dfrac{5}{3}\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8731, 'ដោះស្រាយវិសមីការ \(\dfrac{1-m}{2} + \dfrac{m+5}{6} > 4 - \dfrac{3-m}{3}\) ៖', NULL, '["\\(m > 5\\)", "\\(m > -5\\)", "\\(m < 5\\)", "\\(m < -5\\)"]', 3, NULL, 3, 'mcq', 'គុណនឹង 6 ៖ \(3(1-m) + (m+5) > 24 - 2(3-m) \Rightarrow 8 - 2m > 18 + 2m \Rightarrow -4m > 10 \Rightarrow m < -5\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8732, 'សុខានិងផល្លីលេងក្តារយោល។ សុខាមានម៉ាស \(48\ \text{kg}\) អង្គុយខាងឆ្វេង ហើយផល្លីមានម៉ាស \(x\ \text{kg}\) អង្គុយខាងស្តាំ។ បើក្តារយោលផ្អៀងចុះក្រោមខាងផល្លី ទំនាក់ទំនងម៉ាសផល្លីគឺ៖', 'g8-b5307f87b4.svg', '["\\(x < 48\\ \\text{kg}\\)", "\\(x > 48\\ \\text{kg}\\)", "\\(x = 48\\ \\text{kg}\\)", "\\(x \\ge 50\\ \\text{kg}\\)"]', 1, NULL, 3, 'mcq', 'ក្តារយោលផ្អៀងចុះក្រោមខាងផល្លី មានន័យថាផល្លីធ្ងន់ជាងសុខា ៖ \(x > 48\ \text{kg}\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8733, 'ត្រីកោណ \(ABC\) មួយមានប្រវែងជ្រុង \(AB = 12\), \(BC = x\) និង \(AC = 2x\)។ តាមវិសមភាពត្រីកោណ ប្រវែង \(x\) ត្រូវផ្ទៀងផ្ទាត់ ៖', 'g8-ba29a07a7d.svg', '["\\(2 < x < 8\\)", "\\(x > 4\\)", "\\(x < 12\\)", "\\(4 < x < 12\\)"]', 3, NULL, 3, 'mcq', 'ផលបូកពីរជ្រុងធំជាងជ្រុងទីបី ៖ \(2x - x < 12 < 2x + x \Rightarrow x < 12 < 3x \Rightarrow 4 < x < 12\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8734, 'អេក្រង់កុំព្យូទ័រមួយមានបណ្តោយប្រវែង \(x\ \text{cm}\) និងទទឹងខ្លីជាងពីរដងនៃបណ្តោយចំនួន \(20\ \text{cm}\) (\(2x - 20\))។ ដោយសារទទឹងជាប្រវែងវិជ្ជមាន បណ្តោយ \(x\) ត្រូវផ្ទៀងផ្ទាត់ ៖', 'g8-3b80843344.svg', '["\\(x > 20\\ \\text{cm}\\)", "\\(x < 10\\ \\text{cm}\\)", "\\(x \\ge 10\\ \\text{cm}\\)", "\\(x > 10\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', 'ទទឹង \(2x - 20 > 0 \Rightarrow 2x > 20 \Rightarrow x > 10\ \text{cm}\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8735, 'ក្នុងការប្រឡង វណ្ណាទទួលបានពិន្ទុភាសាខ្មែរ \(x\) និងពិន្ទុប្រវត្តិវិទ្យា \(2x - 1\)។ ដើម្បីឱ្យពិន្ទុមធ្យមនៃមុខវិជ្ជាទាំងពីរយ៉ាងតិច 65 ពិន្ទុ ពិន្ទុភាសាខ្មែរ \(x\) ត្រូវ ៖', NULL, '["\\(x \\le 22\\)", "\\(x \\ge 25\\)", "\\(x \\ge 20\\)", "\\(x \\ge 22\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{x + (2x - 1)}{2} \ge 65 \Rightarrow 3x - 1 \ge 130 \Rightarrow 3x \ge 131 \Rightarrow x \ge 22\) (ពិន្ទុគត់)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8736, 'តាក់ស៊ីមួយគិតថ្លៃសេវាដំបូង 5 000 រៀល និង 2 000 រៀលក្នុងមួយគីឡូម៉ែត្រ។ សុជាតិមានប្រាក់ 35 000 រៀល។ ចម្ងាយផ្លូវអតិបរមា \(d\ \text{(km)}\) ដែលសុជាតិអាចជិះបានគឺ ៖', NULL, '["\\(d \\le 17.5\\ \\text{km}\\)", "\\(d \\le 15\\ \\text{km}\\)", "\\(d \\le 20\\ \\text{km}\\)", "\\(d < 15\\ \\text{km}\\)"]', 1, NULL, 3, 'mcq', '\(5\,000 + 2\,000d \le 35\,000 \Rightarrow 2\,000d \le 30\,000 \Rightarrow d \le 15\ \text{km}\)។', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'វិសមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8737, 'ដោះស្រាយវិសមីការ ក. \(x - 3 \le 7\) ខ. \(2 + 3x < 2x + 1\) រួចផ្ទៀងផ្ទាត់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(x \le 7 + 3 \Rightarrow x \le 10\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8738, 'ដោះស្រាយវិសមីការ ក. \(2x + 7 > 3x - 2\) ខ. \(5m - 4 \ge 4m + 11\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(2x - 3x > -2 - 7 \Rightarrow -x > -9\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8739, 'ដោះស្រាយវិសមីការ \(3x - \dfrac{x}{2} < 1 + \dfrac{x}{3}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'តម្រូវភាគបែងរួម 6 ៖ \(18x - 3x < 6 + 2x\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8740, 'ដោះស្រាយវិសមីការ ក. \(-\dfrac{2}{7}t \ge \dfrac{2}{7}\) ខ. \(2x - 5 + 3x > -5x + 15\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. គុណនឹង \(-\dfrac{7}{2}\) ប្តូរទិសដៅ ៖ \(t \le -1\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8741, 'ដោះស្រាយវិសមីការ \(\dfrac{m}{2} + \dfrac{m}{3} + 2m > 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គុណអង្គទាំងពីរនឹង 6 ៖ \(3m + 2m + 12m > 18\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8742, 'ដោះស្រាយវិសមីការ \(5(x-3) - 9 \ge 4(x-3) + 7x\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្លាតកន្សោម ៖ \(5x - 15 - 9 \ge 4x - 12 + 7x\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8743, 'ដោះស្រាយវិសមីការ \(\dfrac{5(x+1)}{6} - 1 < \dfrac{9x+1}{3} - \dfrac{8x+1}{4}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាគបែងរួម 12 ៖ \(10(x+1) - 12 < 4(9x+1) - 3(8x+1)\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8744, 'ផលដករវាង ២ និងមួយចំនួនធំជាងផលបូករវាង ៣ និងពីរដងនៃចំនួននោះ។ ក. សរសេរវិសមីការ។ ខ. ដោះស្រាយរកចំនួននោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាង \(x\) ជាចំនួននោះ (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8745, 'ដោះស្រាយវិសមីការ \(\dfrac{3x-1}{4} - \dfrac{13-x}{2} < \dfrac{7x}{3} - \dfrac{11(x+3)}{6}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គុណនឹង 12 ៖ \(3(3x-1) - 6(13-x) < 28x - 22(x+3)\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8746, 'ក្រុមហ៊ុនទេសចរណ៍មួយនាំភ្ញៀវទៅអង្គរវត្ត ៣ លើក។ លើកទី ១ មាន ១២០ នាក់ និងលើកទី ២ មាន ២២០ នាក់។ ក. សរសេរវិសមីការរកចំនួនភ្ញៀវលើកទី ៣ \(x\) ដើម្បីឱ្យមធ្យម ៣ លើកយ៉ាងតិច ១៤០ នាក់។ ខ. ដោះស្រាយ និងសន្និដ្ឋាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាង \(x\) ជាចំនួនភ្ញៀវលើកទី ៣ \((x \ge 0)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8747, 'ឡាវីបានទទួលពិន្ទុ 82%, 91% និង 84% ក្នុងការប្រឡងគណិតវិទ្យា ៣ ខែដំបូង។ ក. សរសេរវិសមីការរកពិន្ទុខែទី ៤ \(x\) ដើម្បីឱ្យមធ្យមទាំង ៤ លើកនៅចន្លោះ 80% និង 89%។ ខ. ដោះស្រាយរកចន្លោះពិន្ទុ \(x\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាង \(x\) ជាពិន្ទុខែទី ៤ ៖ \(80 \le \dfrac{82 + 91 + 84 + x}{4} \le 89\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8748, 'ហាងទិញមួកសុវត្ថិភាពថ្លៃ 55 000 រៀលក្នុងមួយមួក និងថ្លៃដឹកជញ្ជូន 250 000 រៀល។ បើលក់ចេញវិញថ្លៃ 80 000 រៀលក្នុងមួយមួក។ ក. កំណត់កន្សោមប្រាក់ចំណេញ។ ខ. រកចំនួនមួកអប្បបរមាដើម្បីបានចំណេញយ៉ាងតិច 800 000 រៀល។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាង \(x\) ជាចំនួនមួក។ ចំណូល \(80\,000x\) ; ដើម \(55\,000x + 250\,000\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8749, 'អេក្រង់កុំព្យូទ័រមួយមានទទឹងខ្លីជាងពីរដងបណ្តោយចំនួន \(20\ \text{cm}\)។ ក. សរសេរកន្សោមទទឹងជាអនុគមន៍នៃបណ្តោយ \(x\)។ ខ. កំណត់លក្ខខណ្ឌវិសមីការដើម្បីឱ្យទទឹងមានប្រវែងពិតប្រាកដ។ គ. រកប្រវែងបណ្តោយអប្បបរមា។', 'g8-3b80843344.svg', '[]', 0, NULL, 5, 'writing', 'ក. តាង \(x\) ជាប្រវែងបណ្តោយ (cm) នាំឱ្យទទឹងគឺ \(w = 2x - 20\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8750, 'ត្រីកោណ \(ABC\) មួយមានប្រវែងជ្រុង \(AB = 12\), \(BC = x\) និង \(AC = 2x\)។ ក. សរសេរវិសមភាពត្រីកោណចំពោះជ្រុងទាំងបី។ ខ. ដោះស្រាយរកចន្លោះតម្លៃនៃ \(x\)។', 'g8-ba29a07a7d.svg', '[]', 0, NULL, 5, 'writing', 'ក. តាមវិសមភាពត្រីកោណ ៖ \(AB + BC > AC \Rightarrow 12 + x > 2x\) (1 ពិន្ទុ)
